use std::{path::PathBuf, time::Instant};
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let archive = PathBuf::from(&args[1]);
    let sri = &args[2];
    let destination = PathBuf::from(&args[3]);
    let start = Instant::now();
    std::thread::scope(|scope| {
        for worker in 0..2 {
            let archive = &archive;
            let destination = destination.join(worker.to_string());
            scope.spawn(move || {
                let store = lpm_store::v2::Store::at(destination);
                let (object, _) = store.extract_object_from_file(archive, sri).unwrap();
                assert_eq!(std::fs::metadata(object.join("payload.bin")).unwrap().len(), 12 * 1024 * 1024);
                assert_eq!(std::fs::read_to_string(object.join(".integrity")).unwrap(), *sri);
            });
        }
    });
    println!("{}", start.elapsed().as_micros());
}

