use std::{io::{BufRead, Write}, net::TcpListener, path::PathBuf, time::Instant};
#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() {
    let args: Vec<_> = std::env::args().collect();
    let body = PathBuf::from(&args[1]);
    let cache = PathBuf::from(&args[2]);
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let url = format!("http://{}", listener.local_addr().unwrap());
    let server = std::thread::spawn(move || {
        let (mut connection, _) = listener.accept().unwrap();
        let mut request = std::io::BufReader::new(connection.try_clone().unwrap());
        let mut line = String::new();
        loop {
            line.clear();
            request.read_line(&mut line).unwrap();
            if line == "\r\n" { break; }
        }
        let mut file = std::fs::File::open(body).unwrap();
        write!(connection, "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nCache-Control: max-age=300\r\nConnection: close\r\n\r\n", file.metadata().unwrap().len()).unwrap();
        std::io::copy(&mut file, &mut connection).unwrap();
    });
    let client = lpm_registry::RegistryClient::new().with_npm_registry_url(url).with_cache_dir(Some(cache));
    let start = Instant::now();
    let metadata = client.get_npm_metadata_direct("history-probe").await.unwrap();
    client.flush_pending_cache_writes().await;
    assert_eq!(metadata.versions.len(), 8192);
    println!("{}", start.elapsed().as_micros());
    server.join().unwrap();
}
